import{_ as r,C as d,o as n,c as s,aj as e,E as o}from"./framework.js";const S=JSON.parse('{"title":"服务集成 | Cms / Settings / Integrations | Documentation","description":"服务集成集中管理站点的 CoreSetting：数据库连接、支付、短信、OAuth 登录、对象存储、JWT 等。页面按 Group 折叠分组；每项显示 名称 与 当前值摘要（列表中为脱敏/截断展示），点击 编辑 打开配置弹窗。","frontmatter":{"title":"服务集成 | Cms / Settings / Integrations | Documentation","description":"服务集成集中管理站点的 CoreSetting：数据库连接、支付、短信、OAuth 登录、对象存储、JWT 等。页面按 Group 折叠分组；每项显示 名称 与 当前值摘要（列表中为脱敏/截断展示），点击 编辑 打开配置弹窗。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/integrations/index.html"}]]},"headers":[],"relativePath":"zh/cms/settings/integrations/index.md","filePath":"cms/settings/integrations/index.md","lastUpdated":1780991406000}'),i={name:"zh/cms/settings/integrations/index.md"};function l(h,t,g,c,m,b){const a=d("DocImage");return n(),s("div",null,[t[0]||(t[0]=e('<h1 id="服务集成" tabindex="-1">服务集成 <a class="header-anchor" href="#服务集成" aria-label="Permalink to &quot;服务集成&quot;">​</a></h1><blockquote><p>菜单：<strong>站点设置 → 服务集成</strong><br> 深链：<code>/_Admin/system/config?SiteId={站点GUID}</code></p></blockquote><p><strong>服务集成</strong>集中管理站点的 <strong>CoreSetting</strong>：数据库连接、支付、短信、OAuth 登录、对象存储、JWT 等。页面按 <strong>Group</strong> 折叠分组；每项显示 <strong>名称</strong> 与 <strong>当前值摘要</strong>（列表中为脱敏/截断展示），点击 <strong>编辑</strong> 打开配置弹窗。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>查看列表：<code>config</code>。编辑并保存任一集成项：<code>config·edit</code>。</p></div><div class="warning custom-block"><p class="custom-block-title">安全</p><p>弹窗内常含 <strong>密钥、连接字符串、证书</strong> 等敏感信息。勿写入公开文档或提交到 Git；CMS 正文只说明 <strong>后台路径与字段含义</strong>，具体取值以厂商控制台为准。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>站点设置 → 服务集成</strong>。</li><li>左侧 <strong>站点设置 → 服务集成</strong>。</li></ol><p>URL 查询参数 <strong><code>group</code></strong> 可展开指定分组，例如从 <a href="./../../database/mysql-table.html">MySQL 表</a> 引导页跳转的 <code>group=Database</code>。</p>',8)),o(a,{src:"/cms/settings/settings-integrations-overview.png",alt:"服务集成总览",width:"1120"}),t[1]||(t[1]=e('<h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><strong>折叠分组</strong></td><td>标题为 Group 名（如 <code>Database</code>、<code>Payment</code>）；可同时展开多个</td></tr><tr><td><strong>行：名称</strong></td><td>集成项 <code>name</code>，与脚本/后台 API 一致（如 <code>Mysql</code>、<code>Alipay</code>）</td></tr><tr><td><strong>行：值</strong></td><td><code>value</code> 摘要（多为 JSON 或连接串片段），过长时省略</td></tr><tr><td><strong>行：编辑</strong></td><td>铅笔按钮，<code>data-cy</code> 为项名；须 <code>config·edit</code></td></tr></tbody></table>',2)),o(a,{src:"/cms/settings/settings-integrations-database.png",alt:"Database 分组",width:"1120"}),t[2]||(t[2]=e('<h2 id="编辑弹窗" tabindex="-1">编辑弹窗 <a class="header-anchor" href="#编辑弹窗" aria-label="Permalink to &quot;编辑弹窗&quot;">​</a></h2><ol><li>点击某一行的 <strong>编辑</strong>。</li><li>顶部 <strong>Alert</strong>（若有）显示厂商回调地址、连接串示例等（来自服务端 <code>GetAlert</code>）。</li><li>表单字段由 <code>CoreSetting/GetFields</code> 动态生成：</li></ol><table tabindex="0"><thead><tr><th>控件类型 <code>type</code></th><th>界面</th></tr></thead><tbody><tr><td>默认</td><td>单行 <strong>文本</strong>（<code>el-input</code>）</td></tr><tr><td><code>checkbox</code></td><td><strong>开关</strong></td></tr><tr><td><code>file</code></td><td><strong>选择文件</strong>（≤10KB，Base64 写入；可删已选文件）</td></tr></tbody></table><ol start="4"><li><strong>确认</strong> 调用 <code>CoreSetting/update</code>，保存后关闭弹窗并刷新列表。</li></ol>',4)),o(a,{src:"/cms/settings/settings-integrations-edit-dialog.png",alt:"编辑集成项弹窗",width:"1120"}),t[3]||(t[3]=e('<div class="info custom-block"><p class="custom-block-title">CMS 与 API 的分工</p><ul><li><strong>本篇（CMS）</strong>：在哪一组、点哪里、字段类型与保存方式。</li><li><strong>API 文档</strong>：脚本调用、回调、<code>k.payment.*</code> 等。支付字段细节见各 <a href="/kb-docs/zh/api/payment/">k.payment</a> 子篇，不在 CMS 重复密钥说明。</li></ul></div><h2 id="分组与文档" tabindex="-1">分组与文档 <a class="header-anchor" href="#分组与文档" aria-label="Permalink to &quot;分组与文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>文档</th><th>典型集成项</th></tr></thead><tbody><tr><td><strong>Database</strong></td><td><a href="./database.html">Database</a></td><td>Mysql、SqlServer、Mongo、Redis、Sqlite</td></tr><tr><td><strong>Payment</strong></td><td><a href="./payment.html">Payment</a></td><td>Alipay、WeChatV3、Stripe、Paypal…</td></tr><tr><td><strong>SMS</strong></td><td><a href="./sms.html">SMS</a></td><td>AliSMS、TencentSMSSetting、ChinaMobileSMSSetting</td></tr><tr><td><strong>OAuth2</strong></td><td><a href="./oauth2.html">OAuth2</a></td><td>Google、Facebook、微信/微博/Apple 登录</td></tr><tr><td><strong>Storage</strong></td><td><a href="./storage.html">Storage</a></td><td>AmazonS3、AliyunOSS、AzureBlob</td></tr><tr><td><strong>Others</strong></td><td><a href="./others.html">Others</a></td><td>JwtSetting、FirebaseSetting</td></tr></tbody></table><p>实际可见项随 Kooboo 版本与已安装模块略有差异，以登录后列表为准。</p><h2 id="与其它菜单的关系" tabindex="-1">与其它菜单的关系 <a class="header-anchor" href="#与其它菜单的关系" aria-label="Permalink to &quot;与其它菜单的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>集成</th><th>配置后常用菜单</th></tr></thead><tbody><tr><td>Database · Mysql / SqlServer</td><td><a href="./../../database/mysql-table.html">MySQL 表</a>、<a href="./../../database/sqlserver-table.html">SQL Server 表</a></td></tr><tr><td>Payment</td><td><a href="./../../commerce/">电商</a>、Code 中 <a href="/kb-docs/zh/api/payment/">k.payment</a></td></tr><tr><td>OAuth2</td><td>前台登录回调；开发侧见 <a href="./../../development/authentication.html">身份验证</a>（JWT 网关规则）</td></tr><tr><td>Storage</td><td><a href="./../../site/media.html">媒体库</a>、内容文件</td></tr><tr><td>JwtSetting</td><td><a href="./../../development/authentication.html">身份验证</a> 规则中的 JWT 校验</td></tr></tbody></table><p>电商 <strong>设置</strong> 页不重复配置 Payment，以本页 <strong>Payment</strong> 分组为准。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>展开对应 <strong>Group</strong>，找到集成项。</li><li><strong>编辑</strong>，按 Alert 提示填写厂商参数并 <strong>保存</strong>。</li><li>到业务菜单验证（如绑 MySQL 后打开 MySQL 表列表、配 Alipay 后走测试支付）。</li><li>脚本侧查阅对应 API 文档。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../">站点设置概述</a></td><td>全部分组菜单</td></tr><tr><td><a href="/kb-docs/zh/api/payment/">k.payment</a></td><td>支付 API</td></tr><tr><td><a href="/kb-docs/zh/api/database/">k.DB</a></td><td>数据库 API</td></tr></tbody></table>',11))])}const u=r(i,[["render",l]]);export{S as __pageData,u as default};
